import {
	Component,
	CUSTOM_ELEMENTS_SCHEMA,
	ViewChild,
	ElementRef,
	OnInit,
	ChangeDetectorRef,
	OnDestroy,
	PLATFORM_ID,
	Inject,
	Input,
	OnChanges,
	SimpleChanges,
	effect,
	ChangeDetectionStrategy,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { environment } from '../../../environments/environment';
import { CommonModule } from '@angular/common';
import { TestimonialService } from '../../providers/testimonial/testimonial.service';
import { TranslationService } from '../../core/services/translation.service';
import { TranslateModule } from '@ngx-translate/core';

@Component({
	selector: 'app-testimonials',
	standalone: true,
	imports: [CommonModule, TranslateModule],
	templateUrl: './testimonials.component.html',
	styleUrl: './testimonials.component.scss',
	schemas: [CUSTOM_ELEMENTS_SCHEMA],
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TestimonialsComponent implements OnInit, OnDestroy, OnChanges {
	@ViewChild('swiperContainer') swiperContainer!: ElementRef;
	@Input() testimonials: any[] = [];
	baseUrl: any;
	imagepath: any;
	activeIndex: number = 0;
	swiperReady: boolean = false;

	private swiperInitialized: boolean = false;
	private intersectionObserver!: IntersectionObserver;
	private isBrowser: boolean;

	constructor(
		private testimonialService: TestimonialService,
		public translationService: TranslationService,
		private cdr: ChangeDetectorRef,
		@Inject(PLATFORM_ID) private platformId: Object, // ✅ inject platform
	) {
		this.baseUrl = environment.url;
		this.imagepath = environment.baseUrl + '/public/';
		this.isBrowser = isPlatformBrowser(this.platformId); // ✅ check once
		effect(() => {
			const locale = this.translationService.currentLang() === 'ar' ? 'ar' : 'en';
		});
	}

	ngOnInit(): void {
		if (!this.isBrowser) return;
		import('swiper/element/bundle').then((m) => {
			m.register();
			this.prepareTestimonials();
		});
	}
	ngOnChanges(changes: SimpleChanges): void {
		if (changes['testimonials'] && this.testimonials?.length > 0) {
			this.prepareTestimonials();
		}
	}
	prepareTestimonials() {
		this.testimonials = this.testimonials.map((t: any) => ({
			...t,
			isExpanded: false,
		}));

		this.cdr.detectChanges();

		setTimeout(() => {
			this.observeVisibility();
		}, 100);
	}
	private observeVisibility(): void {
		// ✅ IntersectionObserver is browser-only
		if (!this.isBrowser) return;

		const swiperEl = this.swiperContainer?.nativeElement;
		if (!swiperEl) {
			window.requestAnimationFrame(() => this.observeVisibility());
			return;
		}

		if (this.intersectionObserver) {
			this.intersectionObserver.disconnect();
		}

		this.intersectionObserver = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting && !this.swiperInitialized) {
						if (this.testimonials.length > 0) {
							// ✅ Safe to use requestAnimationFrame here (browser only)
							window.requestAnimationFrame(() => {
								window.requestAnimationFrame(() => {
									this.initSwiper();
								});
							});
						}
					}
				});
			},
			{ threshold: 0.1 },
		);

		this.intersectionObserver.observe(swiperEl);
	}

	private initSwiper(): void {
		// ✅ Guard browser
		if (!this.isBrowser || this.swiperInitialized) return;

		const swiperEl = this.swiperContainer?.nativeElement;
		if (!swiperEl) {
			console.warn('swiper element not found');
			return;
		}

		// ✅ Retry if dimensions still 0
		const parentWidth = swiperEl.offsetWidth;
		if (parentWidth === 0) {
			window.requestAnimationFrame(() => this.initSwiper());
			return;
		}

		Object.assign(swiperEl, {
			slidesPerView: 1,
			spaceBetween: 0,
			loop: true,
			speed: 900,
			allowTouchMove: true,
			observer: true,
			observeParents: true,
			resizeObserver: true,
			updateOnWindowResize: true,
			autoplay: {
				delay: 3500,
				disableOnInteraction: false,
				pauseOnMouseEnter: false,
			},
			pagination: { clickable: true },
			injectStyles: [
				`
			  .swiper-pagination {
			    bottom: 0px !important;
			    top: auto !important;
			    margin-top: 30px !important;
			    position: relative !important;
			  }
			  .swiper-pagination-bullet-active {
			    background: #de9b7a !important;
			  }
			  .swiper-pagination-bullet {
			    background: #6e6e73;
			    opacity: 1;
					height: 10px;
					width: 10px;
			    margin: 0 5px !important;
			  }
			`,
			],
		});

		swiperEl.initialize();
		this.swiperInitialized = true;

		swiperEl.addEventListener('swiperrealindexchange', (e: any) => {
			this.activeIndex = e.detail[0].realIndex;
			this.cdr.detectChanges();
		});

		setTimeout(() => {
			if (swiperEl?.swiper) {
				swiperEl.swiper.update();
				swiperEl.swiper.autoplay.start();
				this.swiperReady = true;
				this.cdr.detectChanges();
			}
		}, 150);
	}

	goToSlide(index: number): void {
		if (!this.isBrowser) return;
		this.activeIndex = index;
		const swiperEl = this.swiperContainer?.nativeElement;
		if (swiperEl?.swiper) {
			swiperEl.swiper.slideToLoop(index);
		}
	}

	toggleText(testimonial: any): void {
		testimonial.isExpanded = !testimonial.isExpanded;
		this.cdr.detectChanges();
		if (!this.isBrowser) return;
		setTimeout(() => {
			const swiperEl = this.swiperContainer?.nativeElement;
			if (swiperEl?.swiper) {
				swiperEl.swiper.updateSize();
				swiperEl.swiper.updateSlides();
				swiperEl.swiper.update();
			}
		}, 50);
	}

	trackById(index: number, item: any): any {
		return item._id || item.id || index;
	}

	ngOnDestroy(): void {
		if (this.isBrowser && this.intersectionObserver) {
			this.intersectionObserver.disconnect();
		}
	}
}
